import json,os,shutil
from pathlib import Path
import psutil
r={"ram_available":psutil.virtual_memory().available,"cpu_count":os.cpu_count(),"disk_available":shutil.disk_usage("/kaggle/working").free}
Path("/kaggle/working/runtime_resources.json").write_text(json.dumps(r));print(json.dumps(r),flush=True)
assert r["ram_available"]>12*1024**3 and r["disk_available"]>12*1024**3,"runtime capacity insufficient"
import base64,hashlib,os,runpy,sys
from pathlib import Path
os.chdir("/kaggle/working"); sys.path.insert(0,"/kaggle/working")
P={'h1_joint.py': {'base64': '', 'sha256': '974411e9d5fec1661914bab42af14bea35d9b6c189e976808c0adcd2d1e2db43'}, 'pool_adapter.py': {'base64': '', 'sha256': '63e29813b955e42319e0a11e79311429d566a68f35132dd5b850e2e63185334d'}, 'split_rule.py': {'base64': '', 'sha256': '874dac28771e99e93c6f8a4f4633da5090ccd3d63b30a6c063231f015beb9a42'}, 'params.json': {'base64': '', 'sha256': 'da06e456ae0de46295da2734783e1585a1db31eb28611112c1462eacfba78bfb'}}
for name,item in P.items():
 b=base64.b64decode(item["base64"]);
 assert hashlib.sha256(b).hexdigest()==item["sha256"]; Path(name).write_bytes(b)
runpy.run_path('h1_joint.py',run_name="__main__")
